<script setup>
import{ref,watch}from'vue';import{api}from'@/services/api.js';import{Undo2,RotateCcw}from'lucide-vue-next';
const props=defineProps({recordId:String,question:Number});const data=ref(null),error=ref(''),busy=ref(false),operation=ref('add'),operand=ref('1'),explanation=ref('');let generation=0;
const path=()=>'/equation-tools/'+props.recordId+'/'+props.question;
watch(()=>[props.recordId,props.question],async()=>{const g=++generation;data.value=null;error.value='';if(!props.recordId)return;try{const r=await api.request(path());if(g===generation){data.value=r;explanation.value=r.explanation}}catch(e){if(g===generation)error.value=e.message}},{immediate:true});
async function save(action){if(busy.value)return;const g=generation,p=path();busy.value=true;error.value='';let actions=[...data.value.actions];if(action==='step')actions.push({operation:operation.value,value:operand.value});if(action==='undo')actions.pop();if(action==='reset')actions=[];try{const r=await api.request(p,{method:'PUT',body:JSON.stringify({revision:data.value.revision,actions,explanation:explanation.value})});if(g===generation)data.value=r}catch(e){if(g===generation)error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="equation-tool"><SectionHeading title="方程变形"/><p v-if="error" role="alert" class="form-error">{{error}}</p><template v-if="data"><div class="equation-tool-current">{{data.visualization.equation}}</div><div class="exam-toolbar"><select v-model="operation" aria-label="共同运算"><option value="add">两边同加</option><option value="subtract">两边同减</option><option value="multiply">两边同乘</option><option value="divide">两边同除</option></select><Input v-model="operand" aria-label="运算数"/><Button :disabled="busy" @click="save('step')">执行</Button><Button variant="outline" :disabled="busy||!data.actions.length" @click="save('undo')"><Undo2 :size="16"/>撤销</Button><Button variant="ghost" :disabled="busy" @click="save('reset')"><RotateCcw :size="16"/>重置</Button></div><ol><li v-for="(step,i) in data.visualization.steps" :key="i">{{step.equation}}<span>{{step.basis}}</span></li></ol><label>我的解释<Textarea v-model="explanation"/></label><Button variant="outline" :disabled="busy" @click="save('explanation')">保存解释</Button></template></section></template>
